-- =============================================================================================
-- Hand-written below this line: the plan catalogue; existing organisations move to ENTERPRISE
-- (nothing changes for them), new ones get a 30-day ENTERPRISE trial; the application can only
-- read subscriptions (changes come with platform administration, Phase 13 Part 2); every change is
-- logged by the database; plan limits on properties and units are enforced here. See
-- docs/architecture/DATA_MODEL.md section 11 (Subscriptions).
-- =============================================================================================

ALTER TABLE "plans" ADD CONSTRAINT "plans_shape"
  CHECK ("code" ~ '^[A-Z][A-Z0-9_]{1,29}$' AND length(btrim("name")) BETWEEN 1 AND 80
         AND ("max_properties" IS NULL OR "max_properties" >= 1)
         AND ("max_units" IS NULL OR "max_units" >= 1));

INSERT INTO "plans" ("code", "name", "features", "max_properties", "max_units", "position") VALUES
