  ('PROFESSIONAL', 'Professional',
   ARRAY['visitors', 'finance', 'maintenance', 'communications', 'facilities', 'workforce', 'vendors',
         'incidents', 'reporting'], 10, 2000, 2),
  ('ENTERPRISE', 'Enterprise',
   ARRAY['visitors', 'finance', 'maintenance', 'communications', 'facilities', 'workforce', 'vendors',
         'incidents', 'reporting', 'governance', 'integrations'], NULL, NULL, 3);

ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_trial"
  CHECK (("status" = 'TRIAL') = ("trial_ends_at" IS NOT NULL));

CREATE FUNCTION app_subscription_log() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW."plan_code", NEW."status") IS NOT DISTINCT FROM (OLD."plan_code", OLD."status") THEN
    RETURN NULL;
  END IF;
  INSERT INTO "subscription_events" ("id", "organisation_id", "from_plan", "to_plan", "from_status", "to_status",
                                     "reason", "actor_user_id")
  VALUES (gen_random_uuid(), NEW."organisation_id",
          CASE WHEN TG_OP = 'UPDATE' THEN OLD."plan_code" END, NEW."plan_code",
          CASE WHEN TG_OP = 'UPDATE' THEN OLD."status" END, NEW."status",
          nullif(current_setting('app.subscription_reason', true), ''), app_current_user_id());
  RETURN NULL;
END
$$;

CREATE TRIGGER "subscriptions_log"
  AFTER INSERT OR UPDATE ON "subscriptions"
  FOR EACH ROW EXECUTE FUNCTION app_subscription_log();

-- Existing organisations keep everything they have.
INSERT INTO "subscriptions" ("organisation_id", "plan_code", "status")
SELECT "id", 'ENTERPRISE', 'ACTIVE' FROM "organisations";

-- New organisations start a 30-day trial of the full plan (runs as the owner: the application
-- role cannot write subscriptions).
CREATE FUNCTION app_organisation_trial() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
BEGIN
  INSERT INTO "subscriptions" ("organisation_id", "plan_code", "status", "trial_ends_at")
  VALUES (NEW."id", 'ENTERPRISE', 'TRIAL', now() + interval '30 days');
  RETURN NULL;
END
$$;

CREATE TRIGGER "organisations_trial"
  AFTER INSERT ON "organisations"
  FOR EACH ROW EXECUTE FUNCTION app_organisation_trial();

CREATE FUNCTION app_subscription_events_append_only() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  RAISE EXCEPTION 'subscription history is append-only' USING ERRCODE = 'insufficient_privilege';
END
$$;

CREATE TRIGGER "subscription_events_append_only"
  BEFORE UPDATE OR DELETE ON "subscription_events"
  FOR EACH ROW EXECUTE FUNCTION app_subscription_events_append_only();

-- Plan limits. VE401 and VE402 are this application's own error codes (mapped to 409).
CREATE FUNCTION app_plan_limit(org uuid, what text) RETURNS int
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path = public
  AS $$
    SELECT CASE what WHEN 'properties' THEN p."max_properties" ELSE p."max_units" END
      FROM "subscriptions" s JOIN "plans" p ON p."code" = s."plan_code"
     WHERE s."organisation_id" = org
  $$;

CREATE FUNCTION app_property_plan_limit() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  limit_n int := app_plan_limit(NEW."organisation_id", 'properties');
BEGIN
  IF limit_n IS NOT NULL AND (
    SELECT count(*) FROM "properties" WHERE "organisation_id" = NEW."organisation_id" AND "status" <> 'ARCHIVED'
  ) >= limit_n THEN
    RAISE EXCEPTION 'the plan allows at most % properties', limit_n USING ERRCODE = 'VE401';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "properties_plan_limit"
  BEFORE INSERT ON "properties"
  FOR EACH ROW EXECUTE FUNCTION app_property_plan_limit();

CREATE FUNCTION app_unit_plan_limit() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  limit_n int := app_plan_limit(NEW."organisation_id", 'units');
BEGIN
  IF limit_n IS NOT NULL AND (
    SELECT count(*) FROM "units" WHERE "organisation_id" = NEW."organisation_id" AND "status" = 'ACTIVE'
  ) >= limit_n THEN
    RAISE EXCEPTION 'the plan allows at most % units', limit_n USING ERRCODE = 'VE402';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "units_plan_limit"
  BEFORE INSERT ON "units"
  FOR EACH ROW EXECUTE FUNCTION app_unit_plan_limit();

ALTER TABLE "subscriptions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "subscriptions" FORCE ROW LEVEL SECURITY;
CREATE POLICY "subscriptions_select" ON "subscriptions" FOR SELECT USING (organisation_id = app_current_organisation_id());
ALTER TABLE "subscription_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "subscription_events" FORCE ROW LEVEL SECURITY;
CREATE POLICY "subscription_events_select" ON "subscription_events" FOR SELECT USING (organisation_id = app_current_organisation_id());
-- Writes come only from the owner-run functions above (the application role has SELECT only);
-- row-level security still binds them to the tenant in context.
CREATE POLICY "subscriptions_insert" ON "subscriptions" FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id());
CREATE POLICY "subscriptions_update" ON "subscriptions" FOR UPDATE
  USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id());
CREATE POLICY "subscription_events_insert" ON "subscription_events" FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id());

REVOKE ALL ON "plans", "subscriptions", "subscription_events" FROM PUBLIC;
GRANT SELECT ON "plans", "subscriptions", "subscription_events" TO veyra_app;
